alter table public.companies add column pix_key text,add column pix_key_type text check(pix_key_type in('cpf','cnpj','email','telefone','aleatoria')),add column pix_holder_name text,add column pix_bank_name text;
create table public.portal_pix_payments(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),customer_id uuid not null references public.customers(id),auth_user_id uuid not null,appointment_id uuid not null references public.appointments(id),amount numeric(12,2)not null check(amount>0),payer_name text not null,paid_at timestamptz not null,transaction_reference text not null,notes text,status text not null default'pendente'check(status in('pendente','confirmado','recusado')),reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,response_note text,financial_transaction_id uuid references public.financial_transactions(id),created_at timestamptz not null default now());
create index portal_pix_user_idx on public.portal_pix_payments(auth_user_id,created_at desc);create index portal_pix_company_status_idx on public.portal_pix_payments(company_id,status,created_at);create index portal_pix_customer_idx on public.portal_pix_payments(customer_id);create index portal_pix_appointment_idx on public.portal_pix_payments(appointment_id);create index portal_pix_reviewer_idx on public.portal_pix_payments(reviewed_by)where reviewed_by is not null;create index portal_pix_financial_idx on public.portal_pix_payments(financial_transaction_id)where financial_transaction_id is not null;
alter table public.portal_pix_payments enable row level security;create policy portal_pix_select on public.portal_pix_payments for select to authenticated using(auth_user_id=(select auth.uid())or(select private.is_company_member(company_id)));revoke all on public.portal_pix_payments from public,anon,authenticated;grant select on public.portal_pix_payments to authenticated;
create function private.submit_portal_pix(p_appointment uuid,p_amount numeric,p_payer text,p_paid_at timestamptz,p_reference text,p_notes text)returns uuid language plpgsql security definer set search_path=''as $$declare c public.customers;a public.appointments;r uuid;begin c:=private.portal_customer();select*into a from public.appointments where id=p_appointment and customer_id=c.id and company_id=c.company_id;if not found or p_amount<=0 or p_amount>a.expected_price or length(trim(p_payer))<2 or length(trim(p_reference))<3 then raise exception'Dados do Pix inválidos';end if;if exists(select 1 from public.portal_pix_payments where appointment_id=a.id and transaction_reference=trim(p_reference)and status<>'recusado')then raise exception'Comprovante já informado';end if;insert into public.portal_pix_payments(company_id,customer_id,auth_user_id,appointment_id,amount,payer_name,paid_at,transaction_reference,notes)values(c.company_id,c.id,(select auth.uid()),a.id,p_amount,trim(p_payer),p_paid_at,trim(p_reference),p_notes)returning id into r;return r;end$$;
create function public.submit_portal_pix_payment(p_appointment uuid,p_amount numeric,p_payer text,p_paid_at timestamptz,p_reference text,p_notes text default null)returns uuid language sql security invoker set search_path=''as $$select private.submit_portal_pix(p_appointment,p_amount,p_payer,p_paid_at,p_reference,p_notes)$$;
create function public.review_portal_pix_payment(p_payment uuid,p_approve boolean,p_note text default null)returns void language plpgsql security invoker set search_path=''as $$declare c uuid;r public.portal_pix_payments;f uuid;begin select company_id into c from public.profiles where id=(select auth.uid())and is_active and role=any(array['proprietario','administrador','gerente','caixa']);if c is null then raise exception'Acesso negado';end if;select*into r from public.portal_pix_payments where id=p_payment and company_id=c for update;if not found or r.status<>'pendente'then raise exception'Pagamento indisponível';end if;if p_approve then insert into public.financial_transactions(company_id,type,category,description,amount,due_date,payment_date,status,payment_method,customer_id,created_by)values(c,'receita','Pix do Portal',format('Pix manual do agendamento %s',r.appointment_id),r.amount,r.paid_at::date,r.paid_at::date,'pago','pix',r.customer_id,(select auth.uid()))returning id into f;update public.portal_pix_payments set status='confirmado',reviewed_by=(select auth.uid()),reviewed_at=now(),response_note=p_note,financial_transaction_id=f where id=r.id;else if length(trim(p_note))<3 then raise exception'Informe o motivo';end if;update public.portal_pix_payments set status='recusado',reviewed_by=(select auth.uid()),reviewed_at=now(),response_note=trim(p_note)where id=r.id;end if;end$$;
revoke all on function private.submit_portal_pix(uuid,numeric,text,timestamptz,text,text)from public,anon;grant execute on function private.submit_portal_pix(uuid,numeric,text,timestamptz,text,text)to authenticated;revoke all on function public.submit_portal_pix_payment(uuid,numeric,text,timestamptz,text,text),public.review_portal_pix_payment(uuid,boolean,text)from public,anon;grant execute on function public.submit_portal_pix_payment(uuid,numeric,text,timestamptz,text,text),public.review_portal_pix_payment(uuid,boolean,text)to authenticated;
create trigger audit_portal_pix_payments after insert or update or delete on public.portal_pix_payments for each row execute function private.capture_audit_log();
